FINAL_HASHES = {'app/main.py': '57b3827e5a8e7b2d4d413f7575ebc52a2f0140c59bdd392728fd81e862465e4e', 'app/templates/data_tools/school_merger.html': '0b5d9d302987e3112db54e13bbb8c8955e329ec7506d5f1a26832676154397f3', 'app/templates/data_tools/school_merger_plans.html': '6ff302aa3f8ced8d3e07db9dd473d74b2caad551ccc7cd6ec1472c02bdcdce3b', 'app/templates/data_tools/school_merger_result.html': '7f70a34ec2bd5dd551cd7bdd14914aa89f1ac3bea21bcab038aa5aab743d39b5', 'app/services/school_merger_future_service.py': '919826a8caf87563a5d98343a69acafffd4b4e588ae510c565955cf309aed4c8', 'app/routers/school_merger_future.py': 'a4457f453962f9377300a0ee55efd2661c93636b9f101607df3e7e1dcd417e18', 'app/templates/data_tools/school_merger_dashboard_v45.html': '9d6aed17afc023bae4031a400e38550ea3d1765ea3bedded129e1a1ae18e8697', 'app/templates/data_tools/school_merger_future_v45.html': '555110756c9cf3334f3b910df857719ebba70287d3bf6dbf8a0db9fdd0609843', 'app/templates/data_tools/school_merger_future_preview_v45.html': '3afe83aeea38876f426a20d588ec37bb523917a006fb39b6526d50371b77bcbb', 'app/templates/data_tools/school_merger_future_result_v45.html': '109b5560a375237e84e32dfcb462c5be390e2e2523131423adbe11f510564281'}
OLD_HASHES = {'app/main.py': '403cd52be6c2b7e9e1cb5270f4281c8dabcaa4d0e0b16491690576c3054cabde', 'app/templates/data_tools/school_merger.html': '7d0c4c11f5b28c64f6f2c709cfdef4df91e1ad36cf971a2e895978b959477c37', 'app/templates/data_tools/school_merger_plans.html': '9ee70f9d23fe46702fcc207f96139b347e3aca84c85c07832ee2e573deaaa443', 'app/templates/data_tools/school_merger_result.html': '6f0a0bb4a3abb2326b20ddd5d380eeea092501349e9082d158c201c9264a2781'}
DEPENDENCY_HASHES = {'app/routers/school_merger.py': '92e9fd42cc54bdb6d60c4be287ef2988a63502943b69b11715ba8b986d9a121f', 'app/services/school_merger_preview_service.py': 'f38718f6d731677fef5a8ffb717e040ccea70dd94e574d2539e37a0dc385f042', 'app/services/school_merger_execution_service.py': 'f2898c36b42b75d10d297ef264468723ae8d755f717acdd603617fe41dee773d', 'app/services/school_merger_source_audit_service.py': 'a2b6d14bb70d2c512fc8b9a2cb6bc715ac88c283411049bec97a0b357f59dc0e', 'app/services/school_merger_official_registry.py': '8ce1f5f045737c57511a401d49a5fa264b8166b9f84c4063f0af26647505f656', 'app/services/school_merger_service.py': '414fb49a4c5f4fed7b571cc55df381678fe660cd8a675ecaa2f6fd70ebd7827a', 'data/school_merger_official_registry.json': 'f58969c363d9ec81739a9ee2be9d982b542e602c545f17fdc9c2ddcf397eca6a', 'data/school_merger_source_rosters/TH_2025_2026.json': '26b4356ffd9098ac682b1ed74432c443022fcecbe68724336b2adbfd5f053f98', 'data/school_merger_source_corrections.json': '2307bb52bda0b879ab02c3de7c69b95905cbcbcff368100c9829e2d6d6d2ebcc'}
SMOKE_CODE = 'import json\nfrom app.routers.school_merger_future import _dashboard_payload\nfrom app.services.school_merger_future_service import build_future_preview\nfrom app.services.school_merger_service import list_school_years\n\nyears = list_school_years()\ny = next((x for x in years if str(x.get("name") or x.get("school_year") or "").replace("–", "-") == "2026-2027"), None)\nif not y:\n    y = next((x for x in years if int(x.get("id") or 0) == 2), None)\nassert y, "Không tìm thấy năm học 2026-2027 để smoke audit"\nyid = int(y["id"])\n\nd = _dashboard_payload(school_year_id=yid, level_code="TH", commune_id=None)\ncounts = d.get("counts") or {}\nassert sum(int(counts.get(k, 0) or 0) for k in ("KEEP", "DONE", "READY", "BLOCK")) == int(d.get("total") or 0)\n\nready = next((p for p in d.get("rows", []) if p.get("dashboard_state") == "READY" and p.get("target_school") and p.get("source_schools")), None)\npreview_summary = None\nif ready:\n    p = build_future_preview(\n        school_year_id=yid,\n        level_code="TH",\n        source_ids=[int(x["id"]) for x in ready["source_schools"]],\n        target_school_id=int(ready["target_school"]["id"]),\n    )\n    assert p.get("safe_for_execution") is True, p.get("blockers")\n    preview_summary = {\n        "source_ids": [int(x.get("id")) for x in (p.get("source_schools") or [])],\n        "target_id": int((p.get("target_school") or {}).get("id")),\n        "v43": bool(p.get("v43_source_check_ok")),\n        "v41": bool(p.get("v41_state_check_ok")),\n        "simulation": bool(p.get("simulation_ok")),\n        "staff_rollover": int((p.get("simulation_result") or {}).get("staff_rollover_created") or 0),\n    }\n\nout = {"year_id": yid, "dashboard_total": d.get("total"), "counts": counts, "preview": preview_summary}\nprint(json.dumps(out, ensure_ascii=True, default=str))'


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def db_physical_fingerprint(db: Path) -> str:
    h = hashlib.sha256()
    found = False
    for p in (db, Path(str(db) + "-wal")):
        if p.exists():
            found = True
            h.update(p.name.encode("utf-8"))
            with p.open("rb") as f:
                for chunk in iter(lambda: f.read(1024 * 1024), b""):
                    h.update(chunk)
    return h.hexdigest() if found else "MISSING"


def locate_root() -> Path:
    candidates = [Path.cwd(), Path(r"C:\PhoCap"), Path(__file__).resolve().parent]
    for c in candidates:
        if (c / "app" / "main.py").exists() and (c / "data" / "phocap.db").exists():
            return c.resolve()
    raise RuntimeError("Không tìm thấy dự án. Hãy chép bộ cài vào C:\\PhoCap rồi chạy lại.")


def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmpname = tempfile.mkstemp(prefix=path.name + ".", suffix=".tmp", dir=str(path.parent))
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmpname, path)
    finally:
        try:
            if os.path.exists(tmpname):
                os.unlink(tmpname)
        except Exception:
            pass


def fail(msg: str) -> None:
    raise RuntimeError(msg)


def main() -> None:
    root = locate_root()
    db = root / "data" / "phocap.db"
    stamp = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = root / "backups" / f"backup_truoc_bai_sap_nhap_v4_5_{stamp}"
    export_dir = root / "exports" / "Bai_Sap_Nhap_V4_5_Bang_Dieu_Khien_Va_Phat_Sinh"
    report_path = export_dir / f"bao_cao_cai_v4_5_{stamp}.json"
    touched = []
    existed_before = {}
    db_before = db_physical_fingerprint(db)
    smoke_data = None

    print("=" * 104)
    print(TITLE)
    print(f"Dự án: {root}")
    print(f"Database: {db}")
    print("Nguyên tắc: KHÔNG sáp nhập trong bộ cài; KHÔNG chủ động ghi phocap.db.")
    print("=" * 104)

    try:
        # 1) Verify the source baseline/dependencies that define the safety model.
        errors = []
        for rel, expected in DEPENDENCY_HASHES.items():
            p = root / rel
            if not p.exists():
                errors.append(f"Thiếu file nền: {rel}")
                continue
            actual = sha256_file(p)
            if actual != expected:
                errors.append(f"SHA nền không đúng: {rel}: {actual}")
        if errors:
            fail("Không đúng nền V4.4/V4.3.1 đã khóa:\n- " + "\n- ".join(errors))

        # 2) Verify files we will replace. Idempotent re-run is allowed if already final.
        for rel, b64 in EMBEDDED_FILES.items():
            p = root / rel
            if p.exists():
                actual = sha256_file(p)
                allowed = {FINAL_HASHES[rel]}
                if rel in OLD_HASHES:
                    allowed.add(OLD_HASHES[rel])
                if actual not in allowed:
                    fail(f"DỪNG: {rel} đã khác nền dự kiến; SHA={actual}. Không ghi đè để tránh mất sửa đổi khác.")

        # 3) Backup existing touched files.
        backup_dir.mkdir(parents=True, exist_ok=True)
        for rel in EMBEDDED_FILES:
            p = root / rel
            existed_before[rel] = p.exists()
            if p.exists():
                bp = backup_dir / rel
                bp.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(p, bp)

        # 4) Install complete final files.
        for rel, b64 in EMBEDDED_FILES.items():
            p = root / rel
            data = base64.b64decode(b64.encode("ascii"))
            if sha256_bytes(data) != FINAL_HASHES[rel]:
                fail(f"Payload hỏng trước ghi: {rel}")
            atomic_write(p, data)
            touched.append(rel)

        # 5) Verify final bytes.
        for rel, expected in FINAL_HASHES.items():
            actual = sha256_file(root / rel)
            if actual != expected:
                fail(f"SHA sau ghi không đúng: {rel}: {actual}")

        # 6) Compile the Python files that changed/are new.
        for rel in ("app/main.py", "app/services/school_merger_future_service.py", "app/routers/school_merger_future.py"):
            py_compile.compile(str(root / rel), doraise=True)

        # 7) Smoke audit in a clean child process. It is read-only.
        env = os.environ.copy()
        env["PYTHONPATH"] = str(root) + (os.pathsep + env["PYTHONPATH"] if env.get("PYTHONPATH") else "")
        env["PYTHONIOENCODING"] = "utf-8"
        env["PYTHONUTF8"] = "1"
        cp = subprocess.run(
            [sys.executable, "-c", SMOKE_CODE],
            cwd=str(root), env=env,
            capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=180,
        )
        if cp.returncode != 0:
            fail("Smoke audit V4.5 lỗi:\n" + (cp.stdout or "") + (cp.stderr or ""))
        lines = [x.strip() for x in (cp.stdout or "").splitlines() if x.strip()]
        if not lines:
            fail("Smoke audit V4.5 không trả kết quả.")
        try:
            smoke_data = json.loads(lines[-1])
        except Exception:
            fail("Không đọc được JSON smoke audit V4.5:\n" + cp.stdout)

        db_after = db_physical_fingerprint(db)
        if db_after != db_before:
            fail("Database/WAL đã thay đổi trong bộ cài V4.5. Dừng và khôi phục mã nguồn.")

        export_dir.mkdir(parents=True, exist_ok=True)
        report = {
            "installed_at": dt.datetime.now().isoformat(timespec="seconds"),
            "title": TITLE,
            "root": str(root),
            "database_unchanged": True,
            "db_physical_fingerprint": db_before,
            "backup_dir": str(backup_dir),
            "files": {rel: {"sha256": FINAL_HASHES[rel]} for rel in EMBEDDED_FILES},
            "smoke": smoke_data,
            "new_routes": [
                "/cong-cu-du-lieu/sap-nhap-truong/bang-dieu-khien",
                "/cong-cu-du-lieu/sap-nhap-truong/phat-sinh",
            ],
            "notes": [
                "Không có sáp nhập hàng loạt.",
                "Sáp nhập phát sinh hỗ trợ nhiều nguồn -> một đích và có thể khác xã/phường.",
                "Vẫn bắt buộc V4.3 + V4.1 + mô phỏng RAM + backup + transaction + integrity/FK + SAP NHAP.",
            ],
        }
        report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")

        counts = (smoke_data or {}).get("counts") or {}
        print()
        print("=" * 104)
        print("BÀI SÁP NHẬP V4.5 - CÀI ĐẶT THÀNH CÔNG")
        print("Database: KHÔNG THAY ĐỔI")
        print(f"Dashboard TH smoke: tổng {(smoke_data or {}).get('dashboard_total')} | "
              f"GIỮ NGUYÊN {counts.get('KEEP', 0)} | ĐÃ THỰC HIỆN {counts.get('DONE', 0)} | "
              f"READY {counts.get('READY', 0)} | BLOCK {counts.get('BLOCK', 0)}")
        print("Đường dẫn mới:")
        print(" - /cong-cu-du-lieu/sap-nhap-truong/bang-dieu-khien")
        print(" - /cong-cu-du-lieu/sap-nhap-truong/phat-sinh")
        print(f"Backup mã nguồn trước V4.5: {backup_dir}")
        print(f"Báo cáo: {report_path}")
        print("KHÔNG có sáp nhập hàng loạt; KHÔNG thực hiện sáp nhập trong bộ cài này.")
        print("=" * 104)

    except Exception as e:
        # Roll code back. Database was never intentionally written by this installer.
        try:
            for rel in EMBEDDED_FILES:
                p = root / rel
                if existed_before.get(rel):
                    bp = backup_dir / rel
                    if bp.exists():
                        p.parent.mkdir(parents=True, exist_ok=True)
                        shutil.copy2(bp, p)
                else:
                    if p.exists() and rel in touched:
                        p.unlink()
        except Exception:
            pass
        print()
        print("=" * 104)
        print("DỪNG AN TOÀN - BÀI SÁP NHẬP V4.5")
        print("Cài V4.5 không hoàn tất; mã nguồn đã được khôi phục nếu đã chạm file.")
        print(f"Lỗi: {e}")
        if os.environ.get("PHOCAP_INSTALLER_DEBUG") == "1":
            traceback.print_exc()
        print("Bộ cài không thực hiện sáp nhập và không chủ động ghi phocap.db.")
        print("=" * 104)
        raise SystemExit(1)


if __name__ == "__main__":
    main()
